function main(): void {
  const S = Symbol('s');
  const o: any = Object.defineProperties({ a: 1 }, { [S]: { value: 7, enumerable: false, writable: true, configurable: true }, ['a' + 'b']: { value: 8, enumerable: false, writable: true, configurable: true } });
  console.log(o[S], o.ab, Object.getOwnPropertySymbols(o).length, Object.keys(o).join());
  const c: any = Object.assign({}, o);
  console.log(c[S], c.ab, Object.getOwnPropertySymbols(c).length, Object.keys(c).join());
  const sp: any = { ...o };
  console.log(sp[S], sp.ab, Object.getOwnPropertySymbols(sp).length, Object.keys(sp).join());
  console.log(JSON.stringify(o));
}
